import {escapeHtml as esc} from './components.js';
import {readWatchlist} from './watchlist.js';
const topics={financial:'정기·재무',event:'주요 사항',ownership:'내부자·대량보유',offering:'증권 등록·계획',governance:'주주총회',other:'기타'};
const states={body_ready:'영어 본문 확보 · 한국어 핵심 사실 확인 필요',metadata_ready:'공시 목록 확인 · 한국어 유형 안내',collected:'수집 완료 · 핵심 요약 대기',extracting:'핵심 사실 추출 중',summary_ready:'한국어 요약 완료 · 영어 원문 제공',translating:'영어 원문 제공',translated:'영어 원문 제공',translation_review:'원문 확인 필요',review:'원문 확인 필요',error:'처리 실패 · 재시도 대기'};
const errorLabel=value=>String(value||'').startsWith('FINVIZ_')?'Finviz 공시 갱신 실패 · 마지막 저장 자료 표시':String(value||'').includes('UNDECLARED_AUTOMATED_TOOL')?'SEC 자동화 요청 차단(403) · 수집 연결 확인 필요':String(value||'').includes('403')?'SEC 접속 거부(403) · 자동 재시도 대기':String(value||'').includes('COOLDOWN')?'SEC 요청을 잠시 쉬고 있습니다. 자동 재시도 대기':String(value||'').includes('429')?'SEC 요청 제한 · 자동 재시도 대기':value?'SEC 자료 처리 실패 · 원문 확인 필요':'';
const relations={company:'회사 제출',third_party:'임원·주주 등 제3자 제출',pending:'제출자 관계 확인 중',unverified:'대상 회사 관계 확인 필요'};
const url=value=>{try{const u=new URL(value);return u.protocol==='https:'&&['finviz.com','www.sec.gov','data.sec.gov','investors.fastly.com','investor.apple.com','d18rn0p25nwr6d.cloudfront.net'].includes(u.hostname)?u.href:'#';}catch{return '#';}};
function at(value,zone){if(!value)return '시각 미제공';const date=new Date(value);return Number.isFinite(date.getTime())?date.toLocaleString('ko-KR',{timeZone:zone,hour12:false}):'시각 확인 필요';}
const clocks=f=>f.accepted_at?at(f.accepted_at,'America/New_York')+' ET / '+at(f.accepted_at,'Asia/Seoul')+' KST · SEC 접수 시각':(f.filed_date||'날짜 미제공')+' · '+(f.content_id?'공식 IR 공시일':f.list_source?'Finviz 제출일':'SEC 공시 일자')+' (접수 시각 미제공)';
const summaryText=f=>f.summary_ko||f.insider_summary||(f.error?'본문 수집 실패 · 요약을 확인할 수 없습니다.':f.source_hash?'본문에서 핵심 사실을 확인하지 못했습니다. 원문을 확인해 주세요.':(f.state==='metadata_ready'||f.metadata_summary)?'본문 미확보 · SEC 원문에서 내용을 확인하세요.':'공시 내용 확인 중 · 요약 대기');
const stateText=f=>f.insider_summary?'Finviz 거래 내역 확인'+(f.insider_stale?' · 갱신 지연':''):f.metadata_summary&&!f.source_hash?'공시 목록 확인 · 영어 원문 링크 제공':states[f.state]||f.state;
export function mountSecFilings(root,{ticker}){
 let active=false,destroyed=false,timer,controller,version=0,page=1,accession=/^\d{10}-\d{2}-\d{6}$/.test(new URLSearchParams(location.search).get('accession')||'')?new URLSearchParams(location.search).get('accession'):null,documentId=null,offset=0,lastSignature='',contentId=null,view='list';
 root.classList.add('sec-panel');root.innerHTML=`<div class="research-heading"><div><h2>SEC 공시</h2><p>실제 공시 내용 · 한국어 핵심 요약 · 영어 원문</p></div><button data-sec="refresh">새로고침</button></div><div class="sec-view-switch" role="group" aria-label="공시 보기"><button data-sec="view-content" aria-pressed="false">공식 IR 별도 자료</button><button data-sec="view-list" aria-pressed="true">공시 · 한 줄 요약</button></div><p class="sec-status" role="status"></p><div class="sec-filters"><label>기간 시작<input type="date" name="sec-from" aria-label="공시 기간 시작"></label><label>기간 종료<input type="date" name="sec-to" aria-label="공시 기간 종료"></label><label>공시 형식<select name="sec-form" aria-label="공시 형식"><option value="">전체 form</option></select></label><label>주제<select name="sec-topic" aria-label="공시 주제"><option value="">전체 주제</option>${Object.entries(topics).map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></label></div><div class="sec-content"></div><footer class="sec-coverage"></footer>`;
 const $=s=>root.querySelector(s);
 function schedule(){clearTimeout(timer);if(active&&!destroyed)timer=setTimeout(load,15000);}
 async function load(){if(!active||destroyed)return;const v=++version;controller?.abort();controller=new AbortController();const p=new URLSearchParams({ticker,page,view,watched:readWatchlist().includes('US:'+ticker)?'1':'0'});for(const key of ['from','to','form','topic']){const value=$(`[name="sec-${key}"]`).value;if(value)p.set(key,value);}if(contentId){p.set('contentId',contentId);p.set('offset',offset);}if(accession){p.set('accession',accession);p.set('offset',offset);if(documentId)p.set('document',documentId);}
  try{const r=await fetch('/api/sec-filings?'+p,{signal:controller.signal}),data=await r.json();if(v!==version||destroyed)return;if(!r.ok)throw new Error(data.message||'공시 조회 실패');
   $('.research-heading p').textContent=(data.source||'SEC EDGAR')+(view==='content'?' · 실제 내용과 원문 근거':' · 제출 내역');
   const warnings=[data.message,data.target?.error?errorLabel(data.target.error)+' · 마지막 정상 목록을 표시합니다.':'',!data.workerActive?'수집 작업자 대기 · 자동 갱신은 별도 SEC 작업자가 실행 중일 때 동작합니다.':''].filter(Boolean);$('.sec-status').textContent=warnings.join(' ');
   $('.sec-coverage').textContent=`주기적 확인 · 종목별 최소 ${Math.ceil((data.syncIntervalSeconds||900)/60)}분 간격 · 대기 작업에 따라 추가 지연. `+(data.coverage||'')+' · 목록 최종 정상 조회 '+(data.target?.syncedAt?at(data.target.syncedAt,'Asia/Seoul')+' KST':'없음');
   const signature=JSON.stringify(accession||contentId?{filing:data.filing,document:data.document,chunks:data.chunks,facts:data.facts,offset:data.offset}:{items:data.items,forms:data.forms,total:data.total,page});
   if(signature!==lastSignature){lastSignature=signature;if((accession||contentId)&&data.filing)detail(data);else list(data);}
  }catch(e){if(e.name!=='AbortError'&&v===version)$('.sec-status').textContent=e.message;}finally{if(v===version)schedule();}
 }
 function list(data){const select=$('[name="sec-form"]'),value=select.value;select.innerHTML='<option value="">전체 form</option>'+(data.forms||[]).map(f=>`<option value="${esc(f)}">${esc(f)}</option>`).join('');select.value=value;
  $('.sec-filters').hidden=false;$('.sec-content').innerHTML=`<div class="sec-list-count">${data.total||0}개 · 최신 공시순</div>`+(data.items?.length?data.items.map(f=>`<article class="sec-row"><div class="sec-row-meta"><b>${esc(f.form)}</b><span>${esc(topics[f.topic]||'기타')}</span><span>${esc(relations[f.relation]||relations.pending)}</span>${f.amended?'<span>수정공시</span>':''}</div><button class="sec-title" data-sec="open" data-accession="${esc(f.accession||'')}" data-content-id="${esc(f.content_id||'')}">${esc(f.title_ko)}</button><p class="sec-summary">${esc(summaryText(f))}</p>${f.insider_summary?`<a class="sec-summary-evidence" href="${url(f.insider_source_url)}" target="_blank" rel="noopener noreferrer">Finviz 거래 근거 ↗</a>`:''}${f.summary_ko&&f.summary_source_url?`<a class="sec-summary-evidence" href="${url(f.summary_source_url)}" target="_blank" rel="noopener noreferrer">요약 근거 원문 ↗</a>`:''}<p class="sec-row-time">${esc(clocks(f))}</p><div class="sec-row-foot"><span>${esc(f.list_source||'SEC EDGAR')} · ${esc(f.filer_name||'제출자 미제공')} · ${esc(stateText(f))}</span><a href="${url(f.source_url)}" target="_blank" rel="noopener noreferrer">${f.content_id?'공식 IR 원문':'SEC 원문'} ↗</a></div>${f.error&&!f.summary_ko?`<p class="sec-error">${esc(errorLabel(f.error))}</p>`:''}</article>`).join(''):'<p class="research-empty">'+esc(data.message||(data.status==='pending'?'공시 목록을 준비하고 있습니다.':'선택한 조건에서 확인된 공시가 없습니다.'))+'</p>')+`<div class="sec-pager"><button data-sec="previous" ${page<=1?'disabled':''}>이전</button><span>${page} / ${data.pages||1}</span><button data-sec="next" ${page>=(data.pages||1)?'disabled':''}>다음</button></div>`;
 }
 function detail(data){const f=data.filing,doc=data.document;$('.sec-filters').hidden=true;$('.sec-content').innerHTML=`<button class="back-button" data-sec="back">← 공시 목록</button><h3>${esc(f.title_ko)}</h3><p class="sec-summary">${esc(summaryText(f))}</p>${f.insider_summary?`<a class="sec-summary-evidence" href="${url(f.insider_source_url)}" target="_blank" rel="noopener noreferrer">Finviz 거래 근거 ↗</a>`:''}${f.summary_ko&&f.summary_source_url?`<a class="sec-summary-evidence" href="${url(f.summary_source_url)}" target="_blank" rel="noopener noreferrer">요약 근거 원문 ↗</a>`:''}<p class="sec-row-time">${esc(clocks(f))}</p><p class="sec-row-time">보유·보고 기준일 ${esc(f.report_date||'미제공')} · 수집 ${esc(at(f.collected_at,'Asia/Seoul'))} KST</p><p class="sec-row-meta">${esc(f.form)} · ${esc(f.filer_name||'제출자 확인 중')} · ${esc(relations[f.relation])}</p><p class="sec-processing">수집 → 사실 추출 → 한국어 요약 · 영어 원문 제공<br><strong>${esc(stateText(f))}</strong>${f.error?' · '+esc(errorLabel(f.error)):''}${!f.insider_summary&&!f.source_hash&&f.metadata_summary?'<br>본문이 확보되면 확인된 사실을 한 줄로 요약합니다.':''}</p>${f.amended?`<p class="research-note">수정공시 · ${f.original_accession?`<button data-sec="open" data-accession="${esc(f.original_accession)}">원공시 ${esc(f.original_accession)}</button>`:'명시적인 원공시 연결 확인 중 (임의로 직전 공시와 연결하지 않음)'}</p>`:''}<a class="sec-original" href="${url(f.source_url)}" target="_blank" rel="noopener noreferrer">${f.content_id?'발행회사 공식 공시 페이지':'SEC 전체 원문·첨부문서'} ↗</a>${f.content_id?` <a class="sec-original" href="https://www.sec.gov/edgar/browse/?CIK=${encodeURIComponent(f.cik)}&owner=include" target="_blank" rel="noopener noreferrer">SEC 회사 공시 목록 ↗</a><p class="research-note">${esc(f.identity_note)} · ${esc(f.provider_id)} · 공식 IR에 SEC accession 번호가 없어 특정 SEC 공시와 임의 결합하지 않았습니다.</p>`:''}
  ${f.description_en?`<details class="research-note"><summary>Finviz 영문 공시 설명</summary><p>${esc(f.description_en)}</p></details>`:''}<p class="research-note">목록 출처 ${esc(f.list_source||'SEC EDGAR')} · 조회 ${esc(at(f.list_received_at||f.collected_at,'Asia/Seoul'))} KST</p><div class="sec-facts">${(data.facts||[]).map(fact=>`<div><p>${esc(fact.korean)}</p><button data-sec="evidence" data-document="${esc(fact.document_id)}" data-offset="${Math.floor(fact.ordinal/30)*30}">원문 근거 · 문단 ${fact.ordinal+1} →</button></div>`).join('')}</div>
  <label class="sec-document-select"${data.documents.length?'':' hidden'}>문서<select name="sec-document" aria-label="공시 원문 문서">${data.documents.map(d=>`<option value="${d.id}" ${d.id===doc?.id?'selected':''}>${esc(d.form)} · ${esc(d.filename)}${d.source_hash!==f.source_hash?' · 이전 원문 버전':''}</option>`).join('')}</select></label><p class="research-note">본문은 영어 원문입니다. 한국어 핵심 요약은 공시 항목·거래 코드·재무 수치에서 생성하며, 근거가 부족하면 추측하지 않고 원문 확인으로 표시합니다.</p>
  <div class="sec-chunks">${data.chunks.length?data.chunks.map(c=>`<article id="sec-chunk-${c.ordinal}" class="sec-chunk"><div class="sec-chunk-heading"><b>${c.kind==='table'?'표·구조화 자료':'문단'} ${c.ordinal+1}</b><a href="${url(doc.source_url)+(c.anchor?'#'+encodeURIComponent(c.anchor):'')}" target="_blank" rel="noopener noreferrer">${doc.source_url.includes('investors.fastly.com')||f.content_id?'공식 IR 게시 본문':'SEC 문서'} ↗</a></div><pre class="sec-english">${esc(c.english)}</pre></article>`).join(''):'<p class="research-empty">Finviz Export에는 본문이 포함되지 않습니다. 위 SEC 링크에서 영어 원문을 확인할 수 있습니다. SEC 원문이 확보되면 검증된 핵심 사실을 추가합니다.</p>'}</div><div class="sec-pager"><button data-sec="chunk-prev" ${offset===0?'disabled':''}>이전 문단</button><span>${doc?`${Math.min(offset+1,doc.section_count)}~${Math.min(offset+30,doc.section_count)} / ${doc.section_count}개 문단`:'본문 준비 중'}</span><button data-sec="chunk-next" ${!doc||offset+30>=doc.section_count?'disabled':''}>다음 문단</button></div><p class="research-note">원문 해시 ${esc(doc?.source_hash||'대기')} · 처리 버전 ${esc(doc?.version||'대기')}</p>`;
 }
 const change=e=>{if(e.target.name==='sec-document'){documentId=e.target.value;offset=0;}else{page=1;}load();};
 const click=e=>{const b=e.target.closest('[data-sec]');if(!b)return;const a=b.dataset.sec;if(a==='view-content'||a==='view-list'){view=a==='view-content'?'content':'list';page=1;accession=null;contentId=null;documentId=null;offset=0;lastSignature='';for(const button of root.querySelectorAll('.sec-view-switch button'))button.setAttribute('aria-pressed',String(button===b));$('[name="sec-form"]').value='';}else if(a==='open'){contentId=b.dataset.contentId||null;accession=b.dataset.accession||null;documentId=null;offset=0;}else if(a==='back'){contentId=null;accession=null;documentId=null;offset=0;}else if(a==='evidence'){documentId=b.dataset.document;offset=Number(b.dataset.offset);}else if(a==='previous')page--;else if(a==='next')page++;else if(a==='chunk-prev')offset=Math.max(0,offset-30);else if(a==='chunk-next')offset+=30;load();};
 root.addEventListener('click',click);root.addEventListener('change',change);
 return {setVisible(value){active=value;clearTimeout(timer);if(active)load();else{++version;controller?.abort();}},destroy(){destroyed=true;++version;controller?.abort();clearTimeout(timer);root.removeEventListener('click',click);root.removeEventListener('change',change);}};
}
